pub(crate) fn services_manifest() -> IndicatorManifest {
    IndicatorManifest { id: "services", topic_id: "services.status", order: 40, title: "Services Status", icon_id: "server", initial_state: "loading", admin_interactive: true, render_indicator: render_services_indicator, render_modal: render_services_modal, collector: Some(services_collector) }
}

fn render_services_indicator(ctx: IndicatorRenderContext) -> String { let _ = ctx.session; r##"<button type="button" class="indicator warn services-indicator" data-indicator="services" data-modal-kind="services" data-modal-title="Services Status" aria-label="Services Status" title="Services Status"><svg class="indicator-icon" data-packed-icon="server" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 3h16v8H4V3zm2 2v4h12V5H6zm-2 8h16v8H4v-8zm2 2v4h12v-4H6zm9-8h2v2h-2V7zm0 10h2v2h-2v-2z"/></svg></button>"##.to_string() }
fn render_services_modal(ctx: IndicatorRenderContext) -> String { let _ = ctx.session; r##"<div class="services-status-modal" data-modal-kind-body="services"><div class="loading-section" data-modal-status data-route-read="/api/status/services">Loading service status…</div><ul class="service-status-list" data-route-read="/api/status/services"><li>No status data available</li></ul>${indicatorAdminSection(`<div class="admin-service-grid"><div class="admin-service-description">Description</div><div class="admin-service-name">Service</div><div class="admin-service-right"><span class="admin-service-status">enabled</span></div></div><div class="button-row"><button data-modal-fetch="/api/status/services">Refresh</button><button data-modal-fetch="/api/services/data">Service Data</button></div>`)}<pre class="readout action-output" data-modal-output></pre></div>"##.to_string() }
fn services_collector(session: Session) -> Result<serde_json::Value, String> { collect_indicator_topic("services.status", session) }
